// Gera 30 dias fictícios para validar tendência e fadiga sem depender de campanhas reais.
// Cria três cenários: estável, fadiga e melhora. Nada é gravado em fonte externa.
const referencia = DateTime.fromISO('2026-08-12', { zone: 'America/Sao_Paulo' });
const conta = 'CONTA_TESTE';

function criarSerie(id, modo) {
  const resultado = [];

  for (let diasAtras = 29; diasAtras >= 0; diasAtras--) {
    const data = referencia.minus({ days: diasAtras }).toFormat('yyyy-MM-dd');

    let impressoes = 3000;
    let alcance = 2000;
    let cliques = 75;
    let cliquesLink = 60;
    let conversas = 6;
    let investimento = 36;

    if (modo === 'fadiga' && diasAtras <= 6) {
      impressoes = 3400;
      alcance = 1800;

      if (diasAtras > 2) {
        cliques = 52;
        cliquesLink = 38;
        conversas = 3;
        investimento = 42;
      } else {
        cliques = 38;
        cliquesLink = 24;
        conversas = 1;
        investimento = 48;
      }
    }

    if (modo === 'melhora' && diasAtras <= 6) {
      impressoes = 3200;
      alcance = 2200;

      if (diasAtras > 2) {
        cliques = 100;
        cliquesLink = 80;
        conversas = 9;
        investimento = 38;
      } else {
        cliques = 115;
        cliquesLink = 95;
        conversas = 12;
        investimento = 39;
      }
    }

    resultado.push({
      json: {
        'CHAVE REGISTRO': `${data}|${conta}|anuncio|${id}`,
        'DATA REFERENCIA': data,
        'CONTA ANUNCIO': conta,
        'NIVEL ANALISE': 'Anúncio',
        'ID CAMPANHA': 'CAMPANHA_TESTE',
        'NOME CAMPANHA': 'Campanha de Teste',
        'OBJETIVO ORIGINAL': 'CONVERSIONS',
        'ID CONJUNTO': 'CONJUNTO_TESTE',
        'NOME CONJUNTO': 'Conjunto de Teste',
        'ID ANUNCIO': id,
        'NOME ANUNCIO': id,
        'INVESTIMENTO': investimento,
        'IMPRESSOES': impressoes,
        'ALCANCE': alcance,
        'CLIQUES': cliques,
        'CLIQUES LINK': cliquesLink,
        'CONVERSAS INICIADAS': conversas,
        'ORIGEM DADOS': 'TESTE'
      }
    });
  }

  return resultado;
}

return [
  ...criarSerie('ANUNCIO_ESTAVEL', 'estavel'),
  ...criarSerie('ANUNCIO_FADIGA', 'fadiga'),
  ...criarSerie('ANUNCIO_MELHORA', 'melhora')
];

// Compara janelas de 3, 7, 14 e 30 dias e calcula um score de fadiga.
// O score mede deterioração recente; não toma decisões de orçamento.

function numero(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;
  if (typeof valor === 'number') return valor;

  let texto = String(valor).replace(/\s/g, '').replace('R$', '');
  if (texto.includes(',') && texto.includes('.')) texto = texto.replace(/\./g, '').replace(',', '.');
  else if (texto.includes(',')) texto = texto.replace(',', '.');
  return Number(texto) || 0;
}

function dividir(a, b) {
  return b > 0 ? a / b : null;
}

function percentual(a, b) {
  const valor = dividir(a, b);
  return valor === null ? null : valor * 100;
}

function variacao(atual, anterior) {
  if (atual === null || atual === undefined || anterior === null || anterior === undefined || anterior === 0) return null;
  return ((atual - anterior) / anterior) * 100;
}

function arredondar(valor) {
  return valor === null || valor === undefined ? null : Number(valor.toFixed(4));
}

function limpar(item) {
  const novo = {};
  for (const [chave, valor] of Object.entries(item || {})) novo[String(chave).trim()] = valor;
  return novo;
}

function identificarObjeto(item) {
  if (item['ID ANUNCIO']) return { nivel: 'Anúncio', id: String(item['ID ANUNCIO']), nome: item['NOME ANUNCIO'] || item.ANUNCIO || 'Sem nome' };
  if (item['ID CONJUNTO']) return { nivel: 'Conjunto', id: String(item['ID CONJUNTO']), nome: item['NOME CONJUNTO'] || item.CONJUNTO || 'Sem nome' };
  return { nivel: 'Campanha', id: String(item['ID CAMPANHA'] || ''), nome: item['NOME CAMPANHA'] || 'Sem nome' };
}

const base = items
  .map(item => limpar(item.json))
  .filter(item => String(item['CHAVE REGISTRO'] || '').trim() && String(item['DATA REFERENCIA'] || item['DATA INCIO'] || '').trim());

if (!base.length) {
  return [{ json: { status_tendencia: 'SEM_DADOS_HISTORICOS', mensagem: 'Nenhuma série diária com CHAVE REGISTRO foi encontrada.' } }];
}

const datas = base.map(item => String(item['DATA REFERENCIA'] || item['DATA INCIO']));
const dataReferencia = datas.sort().at(-1);
const referencia = DateTime.fromISO(dataReferencia, { zone: 'America/Sao_Paulo' });

const grupos = new Map();

for (const item of base) {
  const objeto = identificarObjeto(item);
  if (!objeto.id) continue;

  const conta = String(item['CONTA ANUNCIO'] || '');
  const objetivo = String(item['OBJETIVO ORIGINAL'] || item.OBJETIVO || '');
  const chave = [conta, objeto.nivel, objeto.id, objetivo].join('|');
  const data = DateTime.fromISO(String(item['DATA REFERENCIA'] || item['DATA INCIO']), { zone: 'America/Sao_Paulo' });
  const diasAtras = Math.round(referencia.diff(data, 'days').days);

  if (diasAtras < 0 || diasAtras > 29) continue;

  if (!grupos.has(chave)) grupos.set(chave, { conta, objetivo, ...objeto, linhas: [] });

  grupos.get(chave).linhas.push({
    data: data.toFormat('yyyy-MM-dd'),
    diasAtras,
    investimento: numero(item.INVESTIMENTO),
    impressoes: numero(item.IMPRESSOES),
    alcance: numero(item.ALCANCE),
    cliques: numero(item.CLIQUES),
    cliquesLink: numero(item['CLIQUES LINK']),
    conversas: numero(item['CONVERSAS INICIADAS'])
  });
}

function calcularJanela(linhas, minimo, maximo) {
  const selecionadas = linhas.filter(linha => linha.diasAtras >= minimo && linha.diasAtras <= maximo);
  const investimento = selecionadas.reduce((s, x) => s + x.investimento, 0);
  const impressoes = selecionadas.reduce((s, x) => s + x.impressoes, 0);
  const cliques = selecionadas.reduce((s, x) => s + x.cliques, 0);
  const cliquesLink = selecionadas.reduce((s, x) => s + x.cliquesLink, 0);
  const conversas = selecionadas.reduce((s, x) => s + x.conversas, 0);
  const frequencias = selecionadas.filter(x => x.alcance > 0).map(x => x.impressoes / x.alcance);
  const dias = new Set(selecionadas.map(x => x.data)).size;

  return {
    dias, investimento, impressoes, cliques, cliquesLink, conversas,
    investimentoDia: dias > 0 ? investimento / dias : null,
    ctrLink: percentual(cliquesLink, impressoes),
    cpc: dividir(investimento, cliques),
    custoConversa: dividir(investimento, conversas),
    taxaCliqueConversa: percentual(conversas, cliquesLink),
    frequenciaMediaDiaria: frequencias.length ? frequencias.reduce((s, x) => s + x, 0) / frequencias.length : null
  };
}

function calcularScoreFadiga(recente3, baseline7, atual7, anterior7) {
  let score = 0;

  const varCtr = variacao(recente3.ctrLink, baseline7.ctrLink);
  const varCpc = variacao(recente3.cpc, baseline7.cpc);
  const varCusto = variacao(recente3.custoConversa, baseline7.custoConversa);
  const varTaxa = variacao(recente3.taxaCliqueConversa, baseline7.taxaCliqueConversa);
  const varFreq = variacao(recente3.frequenciaMediaDiaria, baseline7.frequenciaMediaDiaria);

  if (varCtr !== null) {
    if (varCtr <= -30) score += 20;
    else if (varCtr <= -15) score += 12;
  }

  if (varCpc !== null) {
    if (varCpc >= 30) score += 15;
    else if (varCpc >= 15) score += 8;
  }

  if (recente3.conversas === 0 && recente3.investimento > 0 && baseline7.custoConversa) {
    if (recente3.investimento >= baseline7.custoConversa) score += 30;
  } else if (varCusto !== null) {
    if (varCusto >= 50) score += 30;
    else if (varCusto >= 25) score += 20;
  }

  if (varTaxa !== null) {
    if (varTaxa <= -30) score += 15;
    else if (varTaxa <= -15) score += 8;
  }

  if (varFreq !== null) {
    if (varFreq >= 20) score += 10;
    else if (varFreq >= 10) score += 5;
  }

  const confirmacaoCusto = variacao(atual7.custoConversa, anterior7.custoConversa);
  const confirmacaoCtr = variacao(atual7.ctrLink, anterior7.ctrLink);

  if (confirmacaoCusto !== null && confirmacaoCusto >= 25) score += 5;
  if (confirmacaoCtr !== null && confirmacaoCtr <= -15) score += 5;

  return Math.min(100, score);
}

function classificar(score, suficiente, recente3, baseline7) {
  if (!suficiente) return { classe: 'DADOS INSUFICIENTES', acao: 'Acumular histórico antes de avaliar fadiga.' };
  if (score >= 70) return { classe: 'FADIGA ALTA', acao: 'Priorizar revisão de criativo, oferta e público. Não escalar antes de nova avaliação.' };
  if (score >= 45) return { classe: 'FADIGA MODERADA', acao: 'Preparar nova variação de criativo e acompanhar por mais alguns dias.' };
  if (score >= 25) return { classe: 'OBSERVAR', acao: 'Monitorar a deterioração antes de intervir.' };

  const melhoraCusto = variacao(recente3.custoConversa, baseline7.custoConversa);
  const melhoraCtr = variacao(recente3.ctrLink, baseline7.ctrLink);
  if ((melhoraCusto !== null && melhoraCusto <= -20) || (melhoraCtr !== null && melhoraCtr >= 15)) {
    return { classe: 'MELHORA', acao: 'Manter e confirmar a melhora com mais histórico.' };
  }

  return { classe: 'SAUDÁVEL', acao: 'Sem sinal relevante de fadiga. Manter monitoramento.' };
}

const saida = [];

for (const grupo of grupos.values()) {
  const janela3 = calcularJanela(grupo.linhas, 0, 2);
  const janela7 = calcularJanela(grupo.linhas, 0, 6);
  const janela14 = calcularJanela(grupo.linhas, 0, 13);
  const janela30 = calcularJanela(grupo.linhas, 0, 29);
  const baseline7 = calcularJanela(grupo.linhas, 3, 9);
  const anterior7 = calcularJanela(grupo.linhas, 7, 13);

  const suficiente = janela7.dias >= 5 && baseline7.dias >= 5 && janela7.impressoes >= 1000;
  const score = calcularScoreFadiga(janela3, baseline7, janela7, anterior7);
  const classificacao = classificar(score, suficiente, janela3, baseline7);

  saida.push({
    json: {
      status_tendencia: 'OK',
      data_referencia: dataReferencia,
      conta_anuncio: grupo.conta,
      nivel_analise: grupo.nivel,
      id_objeto: grupo.id,
      nome_objeto: grupo.nome,
      objetivo_original: grupo.objetivo,
      dias_com_dados_7d: janela7.dias,
      dias_com_dados_30d: janela30.dias,
      dados_3d: janela3,
      dados_7d: janela7,
      dados_14d: janela14,
      dados_30d: janela30,
      variacao_3d_vs_baseline_7d: {
        ctr_link: arredondar(variacao(janela3.ctrLink, baseline7.ctrLink)),
        cpc: arredondar(variacao(janela3.cpc, baseline7.cpc)),
        custo_conversa: arredondar(variacao(janela3.custoConversa, baseline7.custoConversa)),
        taxa_clique_conversa: arredondar(variacao(janela3.taxaCliqueConversa, baseline7.taxaCliqueConversa)),
        frequencia_media_diaria: arredondar(variacao(janela3.frequenciaMediaDiaria, baseline7.frequenciaMediaDiaria)),
        investimento_dia: arredondar(variacao(janela3.investimentoDia, baseline7.investimentoDia))
      },
      variacao_7d_vs_7d_anterior: {
        ctr_link: arredondar(variacao(janela7.ctrLink, anterior7.ctrLink)),
        cpc: arredondar(variacao(janela7.cpc, anterior7.cpc)),
        custo_conversa: arredondar(variacao(janela7.custoConversa, anterior7.custoConversa)),
        taxa_clique_conversa: arredondar(variacao(janela7.taxaCliqueConversa, anterior7.taxaCliqueConversa))
      },
      score_fadiga: score,
      classificacao_fadiga: classificacao.classe,
      acao_sugerida: classificacao.acao
    }
  });
}

return saida;

// Consolida o resultado para futura saída do gestor e Motor de Decisão.
if (items.length === 1 && items[0].json.status_tendencia === 'SEM_DADOS_HISTORICOS') return items;

const registros = items.map(item => item.json);
const ordem = { 'FADIGA ALTA': 1, 'FADIGA MODERADA': 2, 'OBSERVAR': 3, 'DADOS INSUFICIENTES': 4, 'SAUDÁVEL': 5, 'MELHORA': 6 };
const classificados = [...registros].sort((a, b) => (ordem[a.classificacao_fadiga] || 99) - (ordem[b.classificacao_fadiga] || 99) || b.score_fadiga - a.score_fadiga);

function contar(classe) { return registros.filter(x => x.classificacao_fadiga === classe).length; }

return [{
  json: {
    status_tendencia: 'OK',
    data_referencia: registros[0]?.data_referencia || '',
    quantidade_objetos: registros.length,
    fadiga_alta: contar('FADIGA ALTA'),
    fadiga_moderada: contar('FADIGA MODERADA'),
    observar: contar('OBSERVAR'),
    saudaveis: contar('SAUDÁVEL'),
    melhora: contar('MELHORA'),
    dados_insuficientes: contar('DADOS INSUFICIENTES'),
    prioridade_fadiga: classificados.filter(x => ['FADIGA ALTA', 'FADIGA MODERADA', 'OBSERVAR'].includes(x.classificacao_fadiga)).slice(0, 10),
    registros_tendencia: registros
  }
}];
